<script lang="ts">
  import type {AppData} from '#lib/client/types.ts';import {display} from '#lib/client/api.ts';import Icon from './Icon.svelte';import Status from './Status.svelte';
  let {data}:{data:AppData}=$props();const font=$derived(data.detail||{});
  function publicUrl(value:string){try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:null;}catch{return null;}}
  const image=$derived(publicUrl(font.thumbnail_url||font.reference_image_url||''));const source=$derived(publicUrl(font.source_url||''));
</script>
<section class="panel"><header class="panel-header"><div><h2>Herstellerreferenz · {font.selection_ref}</h2><p>Die Bildreferenz bleibt von bestellbarer Ausführung und Fertigungsgeometrie getrennt.</p></div><Status value={font.geometry_status||'raster_reference'}/></header><div class="panel-body">{#if image}<div class="font-image"><img src={image} alt={`Tatsächliche Hersteller-Bildreferenz ${font.name} · ${font.selection_ref} · ${display(font.thumbnail_material)}`} loading="lazy" referrerpolicy="no-referrer"/></div><p class="field-help mt">Abgebildete Materialreferenz: {display(font.thumbnail_material)}. Die Abbildung belegt nicht jede andere Materialausführung.</p>{:else}<div class="notice warning"><Icon name="alert"/><div>Zu dieser Schrift liegt noch keine sicher abrufbare Original-Bildreferenz vor.</div></div>{/if}<dl class="definition-list mt"><div><dt>Hersteller / Referenz</dt><dd>{font.manufacturer_name||(font.source_url?.includes('strassacker.com')?'Strassacker':'Hersteller nicht angegeben')} · {font.selection_ref}</dd></div><div><dt>Lieferform</dt><dd>{display(font.supply_form)}</dd></div><div><dt>Geometriestand</dt><dd>{display(font.geometry_status)}</dd></div><div><dt>Rechte / Nutzungsstatus</dt><dd>{display(font.rights_status)}</dd></div></dl>{#if font.material_references}<section class="form-section"><h3>Belegte Materialartikelreferenzen</h3>{#if typeof font.material_references==='object'}<dl class="definition-list">{#each Object.entries(font.material_references) as [material,reference]}<div><dt>{({B:'Bronze',A:'Aluminium',E:'Edelstahl'} as Record<string,string>)[material]||material}</dt><dd>{Array.isArray(reference)?reference.join(' · '):display(reference)}</dd></div>{/each}</dl>{:else}<p class="small">{font.material_references}</p>{/if}</section>{/if}{#if font.catalog_heights}<section class="form-section"><h3>Belegte Katalogoptionen</h3><pre class="json-preview">{typeof font.catalog_heights==='string'?font.catalog_heights:JSON.stringify(font.catalog_heights,null,2)}</pre><p class="field-help mt">Katalogoptionen sind keine pauschalen Auftragshöhen. Wunschhöhe, maximale Breite und Abstände werden im konkreten Entwurf erfasst und bei Bedarf mit dem Hersteller geklärt.</p></section>{/if}<div class="notice info mt"><Icon name="pen"/><div>Eine Bildreferenz eignet sich für Beratung und Spezifikation. Exakte Schrift- oder Bohrschablonen erfordern autorisierte, fachlich verifizierte Kontur- und Befestigungsdaten. Es wird keine ähnliche Ersatzschrift als Herstelleroriginal dargestellt.</div></div><div class="inline-actions">{#if source}<a class="btn" href={source} target="_blank" rel="noreferrer">Originalquelle öffnen<Icon name="link" size={15}/></a>{/if}<a class="btn primary" href="/studio">Planungsstudio öffnen<Icon name="arrow" size={15}/></a></div></div></section>
